+// Fused grad_W split-copy: replaces 3 Python-side .copy_() calls with a
+// single CUDA kernel launch. Reads grad_W_cat[1536, 640] (bf16) and
+// scatters rows to grad_q_weight (1024 rows), grad_k_weight (256 rows),
+// grad_v_weight (256 rows) based on the row index.
+//
+// Layout: 1536 blocks × 80 threads. Each thread handles a 16-byte chunk
+// (int4 = 8 bf16). 80 threads × 8 = 640 cols covered per block. Single
+// vectorized load + single vectorized store per thread.
+// =====================================================================
+
+extern "C" __global__ __launch_bounds__(80) void grad_w_split_copy_kernel(
+    const __nv_bfloat16* __restrict__ src,   // [1536, 640]
+    __nv_bfloat16*       __restrict__ q_dst, // [1024, 640]
+    __nv_bfloat16*       __restrict__ k_dst, // [256,  640]
+    __nv_bfloat16*       __restrict__ v_dst) // [256,  640]
+{
+    int row = blockIdx.x;             // 0..1535
+    int tid = threadIdx.x;            // 0..79
+    // Each row = 640 bf16 = 80 int4 chunks.
+    // Read aligned vec; assumes 16B alignment of torch.empty bf16 tensors (256B aligned).
+    const int4* src4 = reinterpret_cast<const int4*>(src + row * 640) + tid;
+    int4 v = *src4;
+    int4* dst4;
+    if (row < QPROJ) {                              // 0..1023 -> Q
+        dst4 = reinterpret_cast<int4*>(q_dst + row * 640) + tid;
+    } else if (row < QPROJ + KVPROJ) {              // 1024..1279 -> K
+        dst4 = reinterpret_cast<int4*>(k_dst + (row - QPROJ) * 640) + tid;
+    } else {                                         // 1280..1535 -> V
+        dst4 = reinterpret_cast<int4*>(v_dst + (row - QPROJ - KVPROJ) * 640) + tid;
+    }
+    *dst4 = v;
+}
